"""The Portfolio Router: the procurement school (Kraljic-style portfolio routing). Reads the buyer's
`category_goal` and hands the case to one archetype: competitive for leverage items, collaborative for
strategic ones, accommodating for bottleneck ones. The evidence for such a mapping is weak and contested
(SCHOOLS.md, section 6); it is a hypothesis to test, not a proven rule.

Default mapping (constructor knob `mapping`, goal -> archetype name):
  leverage -> anchor (competitive, the buyer has power)      routine -> rational (efficient, game theory)
  stabilise, quality_first -> explorer (collaborative)       secure_supply -> switcher (adaptive)
  unknown or missing goal -> rational

Knobs: mapping (goal -> archetype), agents ({archetype: zero-argument factory}; the defaults import the
real classes lazily, so tests can inject stubs and a broken sibling cannot break this module).
Exposes `chosen` (archetype name) and `goal` after the first decide; logs the choice once per case.
Safety: any delegate error falls back to closing_move, then to a walk-away; an accept that is not
strictly cheaper than the alternative (or not compliant without one) is replaced by closing_move.
"""

import logging

from ..cost import must_haves_ok, total_cost
from ..docs import standard_terms
from ..play import closing_move, live_threads, standing

log = logging.getLogger(__name__)

MAPPING = {
    "leverage": "anchor",
    "routine": "rational",
    "stabilise": "explorer",
    "quality_first": "explorer",
    "secure_supply": "switcher",
}
DEFAULT = "rational"


def _lazy(module, name):
    def make():
        import importlib

        return getattr(importlib.import_module(f".{module}", __package__), name)()

    return make


FACTORIES = {
    "anchor": _lazy("anchor", "AnchorAgent"),
    "rational": _lazy("rational", "RationalAgent"),
    "explorer": _lazy("explorer", "ExplorerAgent"),
    "switcher": _lazy("switcher", "SwitcherAgent"),
    "boulware": _lazy("boulware", "BoulwareAgent"),
}


class RouterAgent:
    def __init__(self, mapping=None, agents=None):
        self.mapping = {**MAPPING, **(mapping or {})}
        self.agents = {**FACTORIES, **(agents or {})}
        self.case_id = self.delegate = self.chosen = self.goal = None

    def _pick(self, case):
        self.goal = case.get("category_goal") or (case.get("buyer") or {}).get("category_goal")
        name = self.mapping.get(self.goal, DEFAULT)
        self.chosen = name if name in self.agents else DEFAULT
        self.case_id, self.delegate = case.get("case_id"), self.agents[self.chosen]()
        log.info("%s: goal %r -> %s", self.case_id, self.goal, self.chosen)

    def decide(self, case, threads):
        try:
            if self.delegate is None or case.get("case_id") != self.case_id:
                self.delegate = None
                self._pick(case)
            decision = self.delegate.decide(case, threads)
            return decision if self._accept_ok(case, threads, decision) else closing_move(case, threads)
        except Exception:  # never crash a case: close safely, else walk away
            log.exception("router delegate failed")
            try:
                return closing_move(case, threads)
            except Exception:
                live = live_threads(threads) or list(threads)
                return {"supplier_id": live[0] if live else None, "message": {"action": {"type": "walk_away"}}}

    @staticmethod
    def _accept_ok(case, threads, decision):
        """False only when an accept is provably not strictly better than the alternative."""
        action = (decision.get("message") or {}).get("action") or {}
        if action.get("type") != "accept":
            return True
        try:
            sid = decision["supplier_id"]
            sheet_id, terms = standing(threads[sid])
            if sheet_id != action.get("term_sheet_id"):
                return True  # cannot check an older sheet safely: leave it to the delegate
            std = standard_terms(threads[sid])
            alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
            if not must_haves_ok(case, terms, std):
                return False
            return not alt.get("unit_price") or total_cost(case, terms, std) < total_cost(case, alt)
        except Exception:
            return True
"""SmartAgent with a confidence index: holds firm while the supplier has room, concedes faster and
accepts earlier as the index falls. Same safety rules as SmartAgent."""

import logging
import math

from ..confidence import confidence_report
from ..cost import complete_offer, must_haves_ok, total_cost
from ..docs import standard_terms
from ..play import closing_move as _closing_move
from ..play import latest, live_threads, moves_left, standing
from .smart import SmartAgent, _quote

log = logging.getLogger("arena")


TONE_HIGH = (
    "Thank you for your offer. We see room on both sides and would like to continue — "
    "could you consider these terms?"
)
TONE_MID = "Thank you, we appreciate the movement. We are getting close; could you consider one of these packages?"
TONE_LOW = (
    "Thank you for working with us on this. We are close to agreement — "
    "if one of these packages works for you we are ready to close."
)

ASK_BETTER = (
    "Thank you. Could you send us a better package, or a breakdown of your costs, "
    "so we can find terms that work for both sides?"
)
QUOTE_ASK = "Could you please send us your quote?"


class ConfidentAgent(SmartAgent):
    def __init__(self, first_cut=0.10, min_step=0.15, max_step=0.60, accept_below=0.25, late=2):
        super().__init__(first_cut=first_cut, late=late)
        self.min_step, self.max_step, self.accept_below = min_step, max_step, accept_below

    def step_for(self, conf):
        """High confidence: small step (push); low confidence: big step (secure the deal)."""
        return self.min_step + (1 - conf) * (self.max_step - self.min_step)

    def decide(self, case, threads):
        live = live_threads(threads)
        for s in live:
            for k, v in standard_terms(threads[s]).items():
                self.std.setdefault((case["case_id"], s), {}).setdefault(k, v)
        std = {s: self.std.get((case["case_id"], s), {}) for s in live}
        closing_move = lambda c, t: _closing_move(c, t, std)  # noqa: E731
        cost = lambda s, t: total_cost(case, t, std[s])  # noqa: E731
        alt = case["buyer"].get("alternative") or {}
        c_alt = total_cost(case, alt["terms"]) if alt.get("terms", {}).get("unit_price") else math.inf
        ok = lambda s, t: must_haves_ok(case, t, std[s]) and cost(s, t) < c_alt  # noqa: E731
        # Threads we can still negotiate in: moves left and not a final offer. Closing a case the
        # way `closing_move` does takes the best safe sheet of ANY thread, or walks away.
        open_ = [
            s for s in live if moves_left(case, threads[s]) > 0 and latest(threads[s]).get("status") != "final_offer"
        ]
        quoting = [s for s in live if standing(threads[s])[1].get("unit_price") is not None]
        if not quoting:
            if not open_:
                return closing_move(case, threads)
            return {"supplier_id": open_[0], "message": {"subject": case["title"], "body": QUOTE_ASK}}
        best = min(quoting, key=lambda s: cost(s, standing(threads[s])[1]))
        if not open_ or (best not in open_ and ok(best, standing(threads[best])[1])):
            return closing_move(case, threads)
        sid = min((s for s in open_ if s in quoting), key=lambda s: cost(s, standing(threads[s])[1]), default=None)
        if sid is None:
            return {"supplier_id": open_[0], "message": {"subject": case["title"], "body": QUOTE_ASK}}
        events = threads[sid]
        sheet_id, terms = standing(events)
        c_open = min([cost(s, q) for s in quoting if (q := _quote(threads[s])).get("unit_price")] or [math.inf])
        c_now, left = cost(sid, terms), moves_left(case, events)
        done = latest(events).get("status") == "agreed"
        report = confidence_report(case, events, std[sid])
        conf = report["score"]
        log.info("%s confidence %.2f %s", sid, conf, report["notes"])
        step = self.step_for(conf)
        early = conf <= self.accept_below and c_now <= c_open and ok(sid, terms)
        log.info("%s step %.2f early accept %s", sid, step, early)
        if (early or (c_now <= c_open and (done or left <= self.late)) or (done and left <= 1)) and ok(sid, terms):
            return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}
        mine = [
            m["term_sheets"][0]["terms"].get("unit_price")
            for m in events
            if m.get("from") == "buyer" and m.get("term_sheets")
        ]
        mine = [x for x in mine if x is not None]
        theirs = terms["unit_price"]
        price = theirs * (1 - self.first_cut) if not mine else mine[-1] + step * (theirs - mine[-1])
        price = min(price, theirs)
        half = theirs - (theirs - price) / 2
        options = case.get("term_options", {})
        longest = max(options.get("contract_months") or [0])
        base = {k: v for k, v in terms.items() if k != "incoterm"}  # complete_offer asks for the cheapest freight
        pay = max(case["buyer"]["reference_payment_days"], (terms.get("payment_days") or 0) + 30)
        asks = [{"unit_price": price}, {"unit_price": half, "payment_days": pay}]
        if "contract_months" in case["negotiable"] and longest:
            asks.append({"unit_price": (price + half) / 2, "contract_months": longest})
        sheets = []
        for ask in asks:
            offer = complete_offer(case, {**base, **ask})
            fits = must_haves_ok(case, offer, std[sid]) and cost(sid, offer) <= min(c_open, c_now)
            if fits and {"terms": offer} not in sheets:
                sheets.append({"terms": offer})
        if not sheets:  # nothing valid to offer: take a safe sheet if there is one, else just move the price
            close = closing_move(case, threads)
            if close["message"].get("action", {}).get("type") == "accept":
                return close
            offer = complete_offer(case, {**terms, "unit_price": price})
            if must_haves_ok(case, offer, std[sid]) and cost(sid, offer) <= c_open:
                sheets = [{"terms": offer}]
            else:  # never send an unsafe sheet: ask in words
                return {"supplier_id": sid, "message": {"subject": case["title"], "body": ASK_BETTER}}
        body = TONE_HIGH if conf >= 0.6 else TONE_MID if conf >= 0.3 else TONE_LOW
        return {"supplier_id": sid, "message": {"subject": case["title"], "body": body, "term_sheets": sheets}}
import logging

from arena_kit.agents.router import RouterAgent

from test_kit import CASE


def _threads(price=40.0):
    return {"sup:A": [{"from": "sup:A", "status": "open",
                       "term_sheets": [{"term_sheet_id": "o0", "terms": {"unit_price": price, "payment_days": 30}}]}]}


def _case(goal, cid="case:T01", alt_price=None):
    buyer = {**CASE["buyer"], "category_goal": goal}
    if alt_price:
        buyer["alternative"] = {"kind": "x", "ref": None, "terms": {"unit_price": alt_price, "payment_days": 60}}
    return {**CASE, "case_id": cid, "buyer": buyer}


def _stub(name):
    class Stub:
        made = []

        def __init__(self):
            self.calls = 0
            Stub.made.append(self)

        def decide(self, case, threads):
            self.calls += 1
            return {"supplier_id": "sup:A", "message": {"subject": name, "body": name}}

    return Stub


def _router(**over):
    stubs = {n: _stub(n) for n in ("anchor", "rational", "explorer", "switcher")}
    return RouterAgent(agents={**stubs, **over}), stubs


def test_each_goal_routes_to_its_archetype():
    for goal, name in [("leverage", "anchor"), ("routine", "rational"), ("stabilise", "explorer"),
                       ("quality_first", "explorer"), ("secure_supply", "switcher")]:
        r, _ = _router()
        assert r.decide(_case(goal), _threads())["message"]["body"] == name
        assert (r.chosen, r.goal) == (name, goal)


def test_unknown_or_missing_goal_routes_to_rational():
    for goal in ("weird", None):
        r, _ = _router()
        assert r.decide(_case(goal), _threads())["message"]["body"] == "rational"
        assert r.chosen == "rational" and r.goal == goal


def test_one_delegate_per_case_reset_on_new_case(caplog):
    r, stubs = _router()
    with caplog.at_level(logging.INFO):
        r.decide(_case("leverage"), _threads())
        r.decide(_case("leverage"), _threads())
    assert len(stubs["anchor"].made) == 1 and stubs["anchor"].made[0].calls == 2
import json

from arena_kit.agents.boulware import BoulwareAgent, target_cost
from arena_kit.cost import total_cost

from test_kit import CASE


def _threads(prices, status="open", sent=()):
    ev = []
    for i, p in enumerate(prices):
        ev.append({"from": "sup:A", "status": status if i == len(prices) - 1 else "open",
                   "term_sheets": [{"term_sheet_id": f"o{i}", "terms": {"unit_price": p, "payment_days": 60}}]})
        if i < len(sent):
            ev.append({"from": "buyer", "term_sheets": [{"terms": {"unit_price": sent[i]}}]})
    return {"sup:A": ev}


def _alt(price, **extra):
    return {**CASE, **extra, "buyer": {**CASE["buyer"], "alternative": {"kind": "x", "ref": None, "terms": {"unit_price": price, "payment_days": 60}}}}


def test_target_curve_rises_from_c_start_to_c_end():
    ts = [target_cost(1000, 900, True, i / 10) for i in range(11)]
    assert all(a <= b for a, b in zip(ts, ts[1:]))  # concession = target cost rises toward the supplier
    assert abs(ts[-1] - 882) < 1e-6  # c_end = 0.98*900 late
    assert abs(ts[0] - 880) < 1e-6 and ts[1] < 881  # starts at c_start, boulware: flat early
    assert abs(target_cost(1000, 0, False, 1.0) - 970) < 1e-6
    assert abs(target_cost(1000, 700, True, 1.0) - 686) < 1e-6 and abs(target_cost(1000, 700, True, 0.0) - 686) < 1e-6  # cheap alternative: never above 0.98*res


def test_offer_never_above_supplier_price():
    msg = BoulwareAgent().decide(_alt(36.0), _threads([44.0, 43.0], "open", [38.0]))["message"]
    assert msg["term_sheets"][0]["terms"]["unit_price"] <= 43.0
    assert set(msg["term_sheets"][0]["terms"]) == {"unit_price", "payment_days"} and "alternative" not in msg["body"]


def test_ac_next_accepts_cheap_standing_sheet():
    msg = BoulwareAgent(ask_payment_days=False).decide(CASE, _threads([44.0, 30.0], "open", [38.0]))["message"]
    assert msg["action"] == {"type": "accept", "term_sheet_id": "o1"}


def test_never_accepts_worse_than_reservation():
    case = _alt(36.0)
    assert total_cost(case, {"unit_price": 40.0, "payment_days": 60}) > total_cost(case, case["buyer"]["alternative"]["terms"])
    for status in ("final_offer", "agreed"):
        assert BoulwareAgent().decide(case, _threads([44.0, 40.0], status, [38.0]))["message"]["action"] == {"type": "walk_away"}
    last = {**case, "round_limit": 1}
    assert BoulwareAgent().decide(last, _threads([44.0, 40.0], "open", [38.0]))["message"]["action"] == {"type": "walk_away"}


def test_final_offer_counter_at_their_price_on_our_terms(monkeypatch):
    monkeypatch.setattr("arena_kit.agents.boulware.standard_terms", lambda ev: {"payment_days": 14})
    th = _threads([44.0, 40.0], "final_offer", [38.0])
    del th["sup:A"][-1]["term_sheets"][0]["terms"]["payment_days"]  # price-only sheet: closes on their 14 days
    msg = BoulwareAgent().decide(_alt(60.0), th)["message"]
    assert msg["term_sheets"][0]["terms"] == {"unit_price": 40.0, "payment_days": 60}
    monkeypatch.setattr("arena_kit.agents.boulware.standard_terms", lambda ev: {})
    assert BoulwareAgent().decide(_alt(60.0), th)["message"]["action"]["type"] == "accept"  # nothing to gain


def test_tit_for_tat_extra_concession_only_when_supplier_moved_more():
    case = _alt(60.0)
    price = lambda prices: BoulwareAgent(ask_payment_days=False).decide(case, _threads(prices, "open", [30.0, 31.0]))["message"]["term_sheets"][0]["terms"]["unit_price"]
    assert price([50.0, 49.0, 46.0]) == 44.35  # moved 1 then 3: plain 44.16 plus 10% of the gap to their cost
    assert price([50.0, 47.0, 46.0]) == 44.16  # moved 3 then 1: plain curve
    assert price([50.0, 49.0, 49.0]) == 44.16  # stalled: plain curve


def test_opponent_model_and_reset_on_new_case():
    a = BoulwareAgent()
    a.decide(CASE, _threads([44.0, 42.0, 41.0], "open", [38.0, 39.0]))
    assert len(a.supplier_costs("sup:A")) == 3 and a.concession_rate("sup:A") > 0
    a.decide({**CASE, "case_id": "case:T02"}, _threads([44.0]))
    assert len(a.supplier_costs("sup:A")) == 1


def test_no_live_threads_does_not_crash():
    ended = {"sup:A": [{"from": "sup:A", "status": "walked_away", "term_sheets": []}]}
    assert BoulwareAgent().decide(CASE, ended)["message"]["action"] == {"type": "walk_away"}
import socket
import threading
import time

import pytest


class Clock:
    """A clock the tests move by hand, so the 60-second rule is testable without waiting."""

    def __init__(self):
        self.now = 1_000_000.0

    def __call__(self):
        return self.now


@pytest.fixture
def sim():
    """arena-sim on a free local port: (base_url, Sim, Clock). Event code 'sim'."""
    pytest.importorskip("fastapi")
    import uvicorn

    from arena_kit.sim import Sim, create_app, load_cases

    clock = Clock()
